values
  ('ia-news-day', 'openai_news', 'OpenAI News', 'https://openai.com/news/rss.xml', 'RSS', 'official', 'high', 5, true, 'Fuente oficial de OpenAI para announcements, producto, modelos y research.', '{}'::jsonb),
  ('ia-news-day', 'anthropic_news', 'Anthropic News', 'https://raw.githubusercontent.com/Olshansk/rss-feeds/main/feeds/feed_anthropic_news.xml', 'RSS', 'official', 'high', 5, true, 'Fuente oficial de Anthropic (Claude, anuncios, safety, enterprise) vía espejo RSS comunitario en GitHub, porque anthropic.com no expone feed. Si el espejo falla, usar https://www.anthropic.com/news como HTML.', '{"espejo_no_oficial":true,"fallback_html":"https://www.anthropic.com/news","unofficial_feed":true,"decision":"Aprobado por Elkin (2026-09-29): sin RSS oficial; se acepta el espejo comunitario Olshansk/rss-feeds por tener fechas reales. Revisar si el chequeo lo marca como stale o broken."}'::jsonb),
  ('ia-news-day', 'anthropic_research', 'Anthropic Research', 'https://raw.githubusercontent.com/Olshansk/rss-feeds/main/feeds/feed_anthropic_research.xml', 'RSS', 'analisis_research', 'medium', 4, true, 'Research y alineación de Anthropic vía espejo RSS comunitario (con fechas). Fallback: https://www.anthropic.com/research.', '{"espejo_no_oficial":true,"fallback_html":"https://www.anthropic.com/research","unofficial_feed":true,"decision":"Aprobado por Elkin (2026-09-29): sin RSS oficial; se acepta el espejo comunitario Olshansk/rss-feeds por tener fechas reales. Revisar si el chequeo lo marca como stale o broken.","subcategory":"research"}'::jsonb),
  ('ia-news-day', 'google_ai_blog', 'Google AI Blog', 'https://blog.google/technology/ai/rss/', 'RSS', 'official', 'high', 5, true, 'Fuente oficial de Google AI.', '{}'::jsonb),
  ('ia-news-day', 'google_deepmind_blog', 'Google DeepMind Blog', 'https://deepmind.google/blog/rss.xml', 'RSS', 'official', 'high', 5, true, 'Modelos, research y avances de DeepMind.', '{"subcategory":"research"}'::jsonb),
  ('ia-news-day', 'microsoft_ai_blog', 'Microsoft AI Blog', 'https://www.microsoft.com/en-us/ai/blog/feed/', 'RSS', 'official', 'medium', 4, true, 'Blog oficial de IA de Microsoft: Copilot, Azure AI, enterprise AI y partnerships.', '{}'::jsonb),
  ('ia-news-day', 'microsoft_research_ai', 'Microsoft Research AI', 'https://www.microsoft.com/en-us/research/feed/?facet%5Btax%5D%5Bmsr-research-area%5D%5B%5D=13556', 'RSS', 'analisis_research', 'low', 2, true, 'Research de IA de Microsoft (área AI del feed de MSR): feed sano y con publicaciones semanales; aporta research explicado desde un laboratorio de referencia.', '{"subcategory":"research"}'::jsonb),
  ('ia-news-day', 'meta_ai_blog', 'Meta AI Blog', 'https://raw.githubusercontent.com/Olshansk/rss-feeds/main/feeds/feed_meta_ai.xml', 'RSS', 'official', 'low', 4, true, 'Modelos abiertos (Llama), research y herramientas de Meta AI vía espejo RSS comunitario. Publica con poca frecuencia.', '{"espejo_no_oficial":true,"unofficial_feed":true,"decision":"Aprobado por Elkin (2026-09-29): sin RSS oficial; se acepta el espejo comunitario Olshansk/rss-feeds por tener fechas reales. Revisar si el chequeo lo marca como stale o broken."}'::jsonb),
