  ('ia-news-day', 'mistral_news', 'Mistral AI News', 'https://mistral.ai/news/rss', 'RSS', 'official', 'medium', 4, true, 'Modelos, producto y announcements de Mistral.', '{}'::jsonb),
  ('ia-news-day', 'techcrunch_ai', 'TechCrunch AI', 'https://techcrunch.com/category/artificial-intelligence/feed/', 'RSS', 'media', 'high', 5, true, 'Startups, negocio, lanzamientos y mercado IA.', '{}'::jsonb),
